def on_left_pressed():
    global xDirection, yDirection
    xDirection = -1
    yDirection = 0
controller.left.on_event(ControllerButtonEvent.PRESSED, on_left_pressed)

def on_countdown_end():
    music.stop_all_sounds()
    game.set_game_over_message(True, "You survived")
    game.game_over(True)
info.on_countdown_end(on_countdown_end)

def on_hit_wall(sprite, location):
    sprites.destroy(sprite, effects.halo, 100)
scene.on_hit_wall(SpriteKind.enemy, on_hit_wall)

def on_right_pressed():
    global xDirection, yDirection
    xDirection = 1
    yDirection = 0
controller.right.on_event(ControllerButtonEvent.PRESSED, on_right_pressed)

def on_on_overlap(sprite2, otherSprite):
    global playerHealth
    animation.run_movement_animation(otherSprite,
        animation.animation_presets(animation.shake),
        200,
        False)
    sprites.destroy(healthUI[playerHealth - 1])
    playerHealth += -1
    pause(200)
    if playerHealth <= 0:
        sprites.destroy(playerCharacter, effects.cool_radial, 500)
        music.stop_all_sounds()
        game.game_over(False)
sprites.on_overlap(SpriteKind.enemy, SpriteKind.player, on_on_overlap)

