def EnemyShooting(EnemyShooter: Sprite, Target: Sprite):
    global enemyBullets, enemyBulletDirectionX, enemyBulletDirectionY, distancePlayerAndEnemy
    enemyBullets = sprites.create(img("""
            . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . 4 . 4 . . . . . . 
                    . . . . . . . . 4 . . . . . . . 
                    . . . . . . . 4 . 4 . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . . 
                    . . . . . . . . . . . . . . . .
        """),
        SpriteKind.enemy)
    enemyBulletDirectionX = Target.x - EnemyShooter.x
    enemyBulletDirectionY = Target.y - EnemyShooter.y
    distancePlayerAndEnemy = Math.sqrt(enemyBulletDirectionX ** 2 + enemyBulletDirectionY ** 2)
    enemyBulletDirectionX = enemyBulletDirectionX / distancePlayerAndEnemy
    enemyBulletDirectionY = enemyBulletDirectionY / distancePlayerAndEnemy
    enemyBullets.set_position(EnemyShooter.x, EnemyShooter.y)
    enemyBullets.set_velocity(enemyBulletDirectionX * bulletSpeed,
        enemyBulletDirectionY * bulletSpeed)

